// `ZtKey::kind`: Option+Backspace.
#define ZT_KEY_OPTION_BACKSPACE 9

// `ZtKey::kind`: forward delete.
#define ZT_KEY_FORWARD_DELETE 10

// `ZtKey::kind`: Escape.
#define ZT_KEY_ESCAPE 11

// `ZtKey::kind`: Tab.
#define ZT_KEY_TAB 12

// `ZtKey::kind`: Shift+Tab.
#define ZT_KEY_SHIFT_TAB 13

// `ZtKey::kind`: ←.
#define ZT_KEY_LEFT 14

// `ZtKey::kind`: →.
#define ZT_KEY_RIGHT 15

// `ZtKey::kind`: ↑.
#define ZT_KEY_UP 16

// `ZtKey::kind`: ↓.
#define ZT_KEY_DOWN 17

// `ZtKey::kind`: Home.
#define ZT_KEY_HOME 18

// `ZtKey::kind`: End.
#define ZT_KEY_END 19

// `ZtKey::kind`: Page Up.
#define ZT_KEY_PAGE_UP 20

// `ZtKey::kind`: Page Down.
#define ZT_KEY_PAGE_DOWN 21

// `ZtKey::kind`: Shift+←.
#define ZT_KEY_SHIFT_LEFT 22

// `ZtKey::kind`: Shift+→.
#define ZT_KEY_SHIFT_RIGHT 23

// `ZtKey::kind`: Shift+↓ (candidates for the one character at the target).
#define ZT_KEY_SHIFT_DOWN 24

// `ZtKey::kind`: Shift+↑ (typing corrections first).
#define ZT_KEY_SHIFT_UP 25

// `ZtComposerOptions::space_action`: Space opens the candidate window.
#define ZT_SPACE_OPEN_CANDIDATES 0

// `ZtComposerOptions::space_action`: Space commits.
#define ZT_SPACE_COMMIT 1

// `ZtComposerOptions::space_action`: Space commits and the app receives the Space.
#define ZT_SPACE_COMMIT_AND_SPACE 2

// `ZtComposerOptions::space_action`: Space puts a space into the composition (as Shift+Space); nothing is sent.
