// Each syllable's candidate characters, passed to a character scorer hook; valid during the callback.  Read with
// the `zt_candidate_rows_*` functions or hand it to
// `zt_syllable_scorer_scores_rows`.
typedef struct ZtCandidateRows ZtCandidateRows;

// One composition state machine.  Used by one thread at a time.
typedef struct ZtComposer ZtComposer;

// An engine: lexicon, language models and personal data.  Thread-safe.
typedef struct ZtEngine ZtEngine;

// A sentence reranker: the decisions of `NeuralReranker` with the host's inference.  Thread-safe.
typedef struct ZtReranker ZtReranker;

// The engine's best sentences, passed to a reranker hook; valid during the callback.  Read with the
// `zt_sentences_*` functions or hand it to `zt_reranker_choose`.
typedef struct ZtSentences ZtSentences;

// A view of strings during a callback (the candidates a candidate scorer orders).  Read with [`zt_strings_count`]
// and [`zt_strings_get`], or hand it to `zt_reranker_candidate_scores_view`.
typedef struct ZtStrings ZtStrings;

// The character model: the decisions of `SyllableScorer` with the host's inference.  Thread-safe.
typedef struct ZtSyllableScorer ZtSyllableScorer;

// The composer's options (Swift's `ComposerOptions`); start from [`zt_composer_options_default`].
typedef struct {
  // Keys that pick candidates 1..n on the current page (UTF-8, one character per key); also sets the page size.
  const char *selection_keys;
  // One of `ZT_SPACE_*`.
  uint32_t space_action;
  // Escape with no window open clears the whole composition.
  bool escape_clears_composition;
  // Learn from commits and picks.
  bool learning_enabled;
  // Longest composition, in syllables.
  size_t max_syllables;
  // One of `ZT_TYPO_*`.
  uint32_t typo_tolerance;
  // One of `ZT_ANCHOR_*`.
  uint32_t candidate_anchor;
  // One of `ZT_DECODER_*`.
  uint32_t key_decoder;
  // The candidate window lists top to bottom.
  bool vertical_list;
  // Moving the highlight past a page's edge turns the page (stopping at the list's ends); false: it stays.
  bool page_at_list_edge;
  // One of `ZT_FORMS_*`.
  uint32_t character_forms;
  // One of `ZT_PUNCTUATION_*`.
  uint32_t punctuation_keys;
} ZtComposerOptions;

// What a key did (Swift's `KeyResult`).
typedef struct {
  // False: the key goes on to the application (after `commit`, if any).
  bool handled;
  // Text to insert before showing the new presentation, or NULL; free with `zt_string_free`.
  char *commit;
} ZtKeyResult;

// A key (Swift's `KeyInput`).
typedef struct {
  // One of the `ZT_KEY_*` constants.
  uint32_t kind;
  // The Unicode scalar for the character kinds; ignored otherwise.
  uint32_t character;
} ZtKey;

// A UTF-16 range.
typedef struct {
  // First unit.
  size_t start;
  // One past the last unit.
  size_t end;
} ZtRange;

// One candidate.
typedef struct {
  // The candidate.
  char *text;
  // Small grey text after it, or NULL.
  char *annotation;
} ZtCandidate;

// The open candidate window.
typedef struct {
  // `count` candidates.
  ZtCandidate *items;
  // How many.
  size_t count;
  // The highlighted index.
  size_t selection;
  // Candidates per page.
  size_t page_size;
  // 1: the list shows typing corrections; 0: only words for the keys as typed; −1: it cannot have corrections.
  int8_t tolerant;
  // Only the one character at the target.
  bool single_character;
} ZtCandidateList;

// What to draw (Swift's `Presentation`).  Offsets are UTF-16 units.
typedef struct {
  // The marked text.
  char *text;
  // The caret in `text`.
  size_t cursor;
  // The words of `text`, for clause underlines.
  ZtRange *clauses;
  // How many clauses.
  size_t clause_count;
  // Index into `clauses` the highlighted candidate replaces, or −1.
  ptrdiff_t focused_clause;
  // Index into `clauses` of the character ↓ would change, or −1.
  ptrdiff_t target_clause;
  // The open candidate window, or NULL.
  ZtCandidateList *candidates;
  // A notice, or NULL.
  char *notice;
  // Standard plain Zhuyin for the highlighted span, or NULL.
  char *zhuyin_hint;
} ZtPresentation;

// The reranker hook (Swift's `Composer.reranker`).
typedef struct {
  // Passed to `choose` and `release`.
  void *context;
  // Chooses the displayed sentence: returns an index into `sentences`, or a negative number to keep the first.
  // NULL removes the hook.
  ptrdiff_t (*choose)(void *context, const ZtSentences *sentences);
  // Called once when the hook is replaced or the composer freed; may be NULL.
  void (*release)(void *context);
} ZtRerankerHook;

// The candidate scorer hook (Swift's `Composer.candidateScorer`).
typedef struct {
  // Passed to `score` and `release`.
  void *context;
  // Scores candidates for list order: writes one score per candidate to `scores` and returns true, or returns
  // false to leave the order as it is.  `before` is the composition text before the candidates' span.  NULL
  // removes the hook.
  bool (*score)(void *context, const char *before, const ZtStrings *candidates, double *scores);
  // Called once when the hook is replaced or the composer freed; may be NULL.
  void (*release)(void *context);
} ZtCandidateScorerHook;

// One syllable as the character model reads it.
typedef struct {
  // Toneless reading (UTF-8), or NULL for a literal.
  const char *base;
  // 0 none (literal), 1 first, 2 ˊ, 3 ˇ, 4 ˋ, 5 ˙.
  int32_t tone;
  // 0 exact … 3 large correction.
  int32_t cost_bucket;
  // The syllable ended without a tone key or Space.
  bool implicit;
} ZtSyllable;

// The character scorer hook (Swift's `Composer.characterScorer`).
typedef struct {
  // Passed to `score` and `release`.
  void *context;
  // Scores each syllable's candidates: row `i` (of `count`) has room for its candidate count of scores, rows
  // packed one after another in `scores`; writes how many it scored (at most the row's length) to `lengths[i]` and
  // returns true, or returns false when it cannot score them.  NULL removes the hook.
  bool (*score)(void *context,
                const ZtSyllable *syllables,
                size_t count,
                const ZtCandidateRows *candidates,
                double *scores,
                size_t *lengths);
  // Called once when the hook is replaced or the composer freed; may be NULL.
  void (*release)(void *context);
} ZtCharacterScorerHook;

// Settings read when an engine is created (Swift's `Engine` static variables).
typedef struct {
  // Score a composition as a whole sentence.
  bool sentence_boundaries;
  // The chat-domain model's directory (`lm_chat/`), or NULL for the encyclopedic model alone.
  const char *chat_model_directory;
  // The share of the sentence-end probability.
  double sentence_end_share;
  // The chat model's prior weight in the mixture.
  double chat_prior;
  // Domain evidence scale.
  double domain_evidence_scale;
  // Domain evidence centre.
  double domain_evidence_centre;
  // Hotspot replacement costs in the typing channel.
  bool hotspot;
  // The reading channel's table (`channel.bin`), or NULL for no reading channel.
  const char *reading_channel;
  // The reading channel's classes in use, one bit per class (`reading-channel.md`).
  uint32_t channel_classes;
  // The classes a single-character word takes variants from.
  uint32_t channel_single_classes;
  // The classes whose variants are corrections.
  uint32_t channel_corrections;
  // The most lexicon readings one typed syllable reaches through the channel.
  uint32_t channel_options_per_syllable;
  // Variants that cost more are left out.
  double channel_max_cost;
  // Third-tone sandhi also reads a typed third tone as the lexicon's second.
  bool channel_sandhi_reverse;
} ZtEngineConfig;

// One personal-data entry.
typedef struct {
  // Its reading, syllables separated by spaces.
  char *reading;
  // The word.
  char *word;
  // For learned words, the learned count; 0 otherwise.
  double count;
} ZtPhrase;

// A list of personal-data entries.
typedef struct {
  // `count` entries.
  ZtPhrase *items;
  // How many.
  size_t count;
} ZtPhraseList;

// A list of owned strings.
typedef struct {
  // `count` strings.
  char **items;
  // How many.
  size_t count;
} ZtStringList;

// The reranker's prefix tree, as the tree model reads it.
typedef struct {
  // `node_count` token IDs (shape `[1, node_count]`).
  const int32_t *ids;
  // `node_count` depths (shape `[1, node_count]`).
  const int32_t *positions;
  // How many nodes.
  size_t node_count;
  // `node_count × node_count` ancestor mask, row-major.
  const int32_t *ancestors;
  // `target_count` parent node indices.
  const int32_t *parents;
  // `target_count` target tokens.
  const int32_t *targets;
  // How many targets (and scores to write).
  size_t target_count;
} ZtPackedTree;

// The host's reranker inference.
typedef struct {
  // Passed to the functions.
  void *context;
  // Required.
  bool (*logprob)(void *context,
                  const int32_t *ids,
                  const int32_t *targets,
                  size_t rows,
                  size_t length,
                  double *logprob);
  // Tree reranker inference: one log probability per target of `tree` out, false when the model cannot run;
  // NULL without a tree model.
  bool (*tree_logprob)(void *context, const ZtPackedTree *tree, double *logprob);
  // Called once when the reranker is freed (or not created); may be NULL.
  void (*release)(void *context);
} ZtRerankerModel;

// The character model's inputs: `count` syllables, each with `width` candidate IDs (row-major, padded with 0).
typedef struct {
  // The text before the composition as character IDs, `<bos>` first.
  const int32_t *context_ids;
  // How many context IDs.
  size_t context_count;
  // `count` toneless reading IDs.
  const int32_t *syllable_ids;
  // `count` tones.
  const int32_t *tones;
  // `count` correction buckets.
  const int32_t *costs;
  // `count` implicit-boundary flags (0 or 1).
  const int32_t *boundaries;
  // How many syllables.
  size_t count;
  // `count × width` candidate character IDs.
  const int32_t *candidates;
  // Candidates per syllable.
  size_t width;
} ZtSyllableInput;

// The host's character model inference.
typedef struct {
  // Passed to the functions.
  void *context;
  // Required.
  bool (*predict)(void *context, const ZtSyllableInput *input, double *logprob);
  // Called once when the scorer is freed (or not created); may be NULL.
  void (*release)(void *context);
} ZtSyllableModel;

// The result of [`zt_syllable_scorer_check_vectors`].
typedef struct {
  // Vectors within tolerance.
  size_t passed;
  // Vectors checked.
  size_t total;
  // The largest absolute difference.
  double worst;
} ZtVectorCheck;

